insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, visibility, sort_order) values ('cn10_h10', 'cm_p21_260820', 'history', '260914 顧客工場の装置の消耗品・電力・点検・交換部品を顧客の持ち分にし、オフサイトの循環カートリッジの運転をSXにした', '2026-09-14、まさの返事で次を決めた。

**なぜ変えたか**
- 汚泥の処分を顧客のままにするか、SXが回収して処分するか → まさ「オンサイトなら顧客」（いまの形のまま）
- 循環カートリッジの処理の運転が「顧客」で保存されていて、オフサイトでも顧客の作業になっていた → まさ「オフサイトならSX」
- 顧客の装置の消耗品・電力・点検と、モジュールの交換費をSXの原価に残すか → まさ「それ普通いれないでしょ」

**何を変えたか**
- 顧客工場の装置を動かす費用を「処理する場所の持ち主」にした（オンサイトは顧客、オフサイトはSX）。循環カートリッジ10行（洗浄・監視点検・保守・菌体保持モジュール交換費・電力）、直接投入17行（洗浄・監視点検・保守・膜の洗浄・逆洗・前処理・差圧監視・回収残渣対応・電力）、処理水の色・COD分析と処理水の不活化の薬剤
- 顧客工場の処理設備の密閉性能検査と除菌フィルター交換（強化株）も、処理する場所の持ち主にした
- 循環カートリッジの処理の運転を「処理する場所の人」にした（オンサイトは顧客、オフサイトはSX）
- SXに残したもの: 菌体の補充分（ロス・性能低下）、菌体を運ぶ巡回と容器、モジュールや膜の交換の作業、顧客工場の立入制限と教育訓練（強化株）、金属回収の酸処理と回収物の分析

**数字**（円/m³、年間処理量 20,000,000m³）:

| 株 | 用途 | オンサイト・直接投入 | オンサイト・循環カートリッジ | オフサイト・直接投入 | オフサイト・循環カートリッジ |
|---|---|---|---|---|---|
| 自然株 | 色素分解 | 81.1 → 30.4 | 360.9 → 33.2 | 2,859.6 → 2,859.6 | 2,795.0 → 3,025.0 |
| 自然株 | 金属回収 | 291.5 → 244.8 | 571.3 → 247.7 | 3,027.0 → 3,027.0 | 2,962.5 → 3,192.5 |
| 強化株 | 色素分解 | 101.8 → 34.1 | 381.6 → 37.0 | 2,880.0 → 2,880.0 | 2,815.4 → 3,045.4 |
| 強化株 | 金属回収 | 289.5 → 225.8 | 569.3 → 228.6 | 3,026.1 → 3,026.1 | 2,961.6 → 3,191.6 |

オンサイトはSXの原価から装置の費用が外れた分だけ下がり、オフサイト・循環カートリッジはSXの運転の分（230円/m³）だけ上がった。オフサイト・直接投入は変わらない。', 'amd_internal', 100);

-- 5. 確認事項
update project_cost_questions set why_it_matters = '菌体使用回数は総コスト最大の感度。1回のままだと菌体の製造原価がそのまま効き、10回を超えると菌体費は1割以下になる。20回と50回の差はほとんど無いので「10回を超えるか」だけ言い切れれば足りる。まさの記憶では数十回いける可能性があるが2026-08-23時点で未確認。 2026-09-14 から10回で置いている（2026-07の設備アドオン試算と同じ前提）。1回しか使えなければ、強化株・オンサイト・直接投入の総コストは34.1円/m³から190.0円/m³へ上がる。', impact_low = 22, impact_high = 156, updated_at = now() where cost_question_id = 'cq_260820_01' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set why_it_matters = '循環カートリッジの菌体保持モジュール交換費は、耐用50バッチで300円/m³（20回なら750円/m³、100回なら150円/m³）。オンサイトでは顧客の装置の費用なのでSXの原価には入らないが、顧客の運転費として循環カートリッジを選んでもらえるかがこの1行で決まる。SXの原価に効くのは、SX工場で処理するオフサイトだけ。', updated_at = now() where cost_question_id = 'cq_260820_04' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set why_it_matters = '上のバッチ数と掛け合わせで300円/m³が決まる。単価も耐用回数もSX予測のままなので、循環カートリッジの数字は現状ほぼ根拠がない。オンサイトでは顧客の装置の費用（SXの原価に効くのはオフサイトだけ）。', updated_at = now() where cost_question_id = 'cq_260820_05' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set why_it_matters = '260820版は人件費を総コストへ入れておらず（参考値で循環カートリッジ230円/m³、直接投入300円/m³）、菌体の搬入・搬出や交換の作業も入っていなかった。二段階版からは、作業リストに手動運用の作業時間と巡回の作業を入れている。無人運転で実際に残る作業と時間が分かれば、作業リストの工数と回数を置き換える。 2026-09-14 から、顧客工場での処理の運転は顧客がやる作業としてSXの原価に入れていない。運転の時間がSXの原価に効くのは、SX工場でSXが運転するオフサイト（いまの工数で循環カートリッジ230円/m³、直接投入300円/m³）。', updated_at = now() where cost_question_id = 'cq_260820_06' and cost_model_id = 'cm_p21_260820';
update project_cost_questions set why_it_matters = '強化株の閉鎖系費用は全て仮置き（カテゴリー1相当）。第1段の菌体原価に乗る。顧客工場の処理設備の閉鎖系の設備・検査・薬剤は顧客が持つので、現場の分がSXの総コストに乗るのはSX工場で処理するオフサイトだけ。GILSPと判定されれば一部が不要になる。', updated_at = now() where cost_question_id = 'cq2_01' and cost_model_id = 'cm_p21_260820';

